const pairedClaims = Object.freeze({
  key_details: ['what_happened', 'where', 'who', 'number_detail'],
  sequencing: ['story_event_order'],
  main_idea: ['mostly_about_info'],
  cause_effect: ['find_effect', 'find_cause', 'because_sentence'],
  theme: ['lesson_mistake_fixed'],
  informational_features: ['supporting_detail', 'purpose'],
});

export const MOCK_V4_COMPREHENSION_APPROVED_TASKS = Object.freeze(Object.entries(pairedClaims).flatMap(([skillId, claims]) => claims.flatMap(constructClaim => {
  const reading = { skillId, domainId: 'reading', constructClaim, modality: 'reading', evidenceModality: 'text', displayPassageDuringResponse: true };
  return skillId === 'informational_features' ? [reading] : [reading, { skillId: `listen_${skillId}`, domainId: 'listening', constructClaim: `listening_${constructClaim}`, modality: 'listening', evidenceModality: 'audio', displayPassageDuringResponse: false }];
})));

export const MOCK_V4_COMPREHENSION_FIXED_ONLY_CLAIMS = Object.freeze([
  ['main_idea', 'mostly_about_fiction'], ['main_idea', 'mostly_about_everyday'],
  ['theme', 'lesson_kindness_returned'], ['theme', 'lesson_effort_pays'],
].flatMap(([skillId, constructClaim]) => [{ skillId, constructClaim }, { skillId: `listen_${skillId}`, constructClaim: `listening_${constructClaim}` }]));

const retiredSkills = new Set(Object.keys(pairedClaims).filter(skill => skill !== 'informational_features').flatMap(skill => [skill, `listen_${skill}`]));

/** Reband predecessors honestly; frozen v3 snapshots are never mutated. */
export function correctLiteracyMockComprehensionV4(item) {
  if (item.tutorialOnly || item.id.startsWith('mock.v4.comprehension.')) return item;
  if (item.taskDemand?.fixedOnly && item.sourceProvenance?.v4Rebanding?.file === FILE) return item;
  const replace = retiredSkills.has(item.skillId) || (item.skillId === 'informational_features' && ['supporting_detail', 'purpose'].includes(item.constructClaim));
  if (!replace) return item;
  const result = { ...item, contentVersion: 'literacy-mock-v4', level: 1, demandCeiling: 1,
    ceilingReason: 'This predecessor is retained as fixed entry evidence. New v4 mixed rounds use the independently reviewed paired comprehension pool.',
    ceilingNextTask: 'Use the new v4 paired comprehension task after a fresh entry observation.',
    adaptiveMixedEligible: false,
    taskDemand: { reviewed: false, fixedOnly: true, operation: item.constructClaim, reason: 'The full predecessor pool does not establish a consistent harder contrast.' },
    sourceProvenance: { ...item.sourceProvenance, v4Rebanding: { file: FILE, originalLevel: item.level } },
  };
  result.itemSnapshot = clone(result);
  delete result.itemSnapshot.itemSnapshot;
  return result;
}

function makePair(bank, skill, claim, id, prompt, entry, harder, entryLabels, harderLabels, demand, proof) {
  const modalities = skill === 'informational_features' ? ['reading'] : ['reading', 'listening'];
  return modalities.flatMap(modality => [1, 2].map(level => {
    const listening = modality === 'listening';
    const skillId = listening ? `listen_${skill}` : skill;
    const constructClaim = listening ? `listening_${claim}` : claim;
    const template = bank.find(item => item.skillId === skillId && item.constructClaim === constructClaim);
    if (!template) throw new Error(`Missing paired comprehension template ${skillId}/${constructClaim}`);
    const sourceId = `mock.v4.comprehension.${skillId}.${claim}.l${level}.${id}`;
    const passage = level === 1 ? entry : harder;
    const labels = level === 1 ? entryLabels : harderLabels;
    const choices = labels.map((label, index) => ({ id: `c${index}`, label }));
    const requiredAudioCues = [{ role: 'instruction', text: prompt, path: getLedaInstructionAudioPath(prompt) }];
    if (listening) {
      requiredAudioCues.unshift({ role: 'passage', text: passage, path: getLedaInstructionAudioPath(passage) });
      requiredAudioCues.push(...choices.map(choice => ({ role: 'choice', choiceId: choice.id, value: choice.label, text: choice.label,
        path: getLedaWordAudioPath(choice.label) || getLedaInstructionAudioPath(choice.label) })));
    }
    const exposureFamilyId = `v4-comprehension:${skill}:${skill === 'key_details' ? `${claim}:` : ''}${id}`;
    const result = { ...template, id: sourceId, sourceItemId: sourceId, canonicalItemId: sourceId.replace('listen_', ''),
      contentVersion: 'literacy-mock-v4', skillId, domainId: listening ? 'listening' : 'reading', level, constructClaim,
      format: 'choice', formatType: 'COMPREHENSION_PAIRED_V4', sourceFormat: 'COMPREHENSION_PAIRED_V4', answerMode: 'exact', prompt, passage,
      choices, answer: 'c0', targetWord: '', renderTargetText: false, image: '', imageAlt: '',
      evidenceModality: listening ? 'audio' : 'text', modality, displayPassageDuringResponse: !listening,
      hideWrittenLabels: false, tutorialOnly: false, requiredAudioCues, requiredImagePaths: [],
      stimulusKey: normalized(passage), canonicalPassageId: exposureFamilyId, exposureFamilyId,
      explanation: level === 1 ? `The supplied single relevant relation supports “${labels[0]}”.` : proof.key,
      distractorRationales: Object.fromEntries([1, 2].map(index => [`c${index}`, level === 1
        ? `“${labels[index]}” does not answer the stated relation in this entry passage.` : proof.foils[index - 1]])),
      difficultyEvidence: level === 1 ? demand.lower : demand.higher,
      taskDemand: { reviewed: true, operation: claim, level, lower: demand.lower, higher: demand.higher,
        features: level === 1 ? demand.entryFeatures : demand.harderFeatures,
        choiceCount: 3, passageWordCount: passage.split(/\s+/).length, proof: level === 2 ? proof : { key: labels[0] } },
      sourceProvenance: { kind: 'original_mock_v4_paired_comprehension', file: FILE, sourceId: id, claim,
        demand: { operation: claim, ...demand }, pairedFamily: exposureFamilyId },
      mediaDecision: { role: 'text-only', paths: [], constructReview: 'approved', answerNeutral: 'approved',
        reason: listening ? 'The exact passage and choices require recorded audio; missing cues fail closed.' : 'The complete printed passage supplies the evidence; only the question is narrated.' },
    };
    delete result.itemSnapshot;
    delete result.demandCeiling;
    delete result.ceilingReason;
    delete result.ceilingNextTask;
    delete result.adaptiveMixedEligible;
    delete result.passageAccess;
    delete result.oralLanguageAccess;
    result.requiredAudioPaths = [...new Set(requiredAudioCues.map(cue => cue.path).filter(Boolean))];
    result.missingAudioCues = requiredAudioCues.filter(cue => !cue.path).map(({ role, text, choiceId }) => ({ role, text, ...(choiceId ? { choiceId } : {}) }));
    result.mediaReady = result.missingAudioCues.length === 0;
    return result;
  }));
}

export function buildLiteracyMockComprehensionLaddersV4(bank) {
  const result = [];
  for (const [claim, rows] of Object.entries(detailRows)) for (const [id, prompt, entry, harder, labels, keyEvidence, foilEvidence] of rows) {
    const count = claim === 'number_detail';
    result.push(...makePair(bank, 'key_details', claim, id, prompt, entry, harder, labels, labels,
      { lower: 'Retrieve one explicitly stated relevant actor, object, place or count.',
        higher: count ? 'Bind a count to both requested attributes; each competing count matches only one.' : 'Bind the requested object or actor to its role or stage while separating two related roles or stages.',
        entryFeatures: { relevantBindings: 1, competingBindingRoles: 0 }, harderFeatures: { relevantBindings: count ? 2 : 1, competingBindingRoles: 2 } },
      { key: `“${labels[0]}” fits the requested relation: ${keyEvidence}.`, foils: foilEvidence.map((fact, index) => `“${labels[index + 1]}” belongs to a different role or stage: ${fact}.`), evidence: [keyEvidence, ...foilEvidence] }));
  }
  for (const [id, entry, harder, labels] of sequenceRows) result.push(...makePair(bank, 'sequencing', 'story_event_order', id, 'What happened first?', entry, harder, labels, labels,
    { lower: 'Find the first event in a chronological account.', higher: 'Resolve two before/after links when the account describes the final event first.',
      entryFeatures: { temporalLinks: 0, presentationConflicts: 0 }, harderFeatures: { temporalLinks: 2, presentationConflicts: 1 } },
    { key: `“${labels[0]}” precedes the middle event, which precedes the opening-mentioned final event.`,
      foils: [`“${labels[1]}” is after the first event, although it is before the final event.`, `“${labels[2]}” is mentioned first but occurs after both other events.`], chronology: labels }));
  for (const [id, entry, harder, entryKey, entryFoil1, entryFoil2, key, foil1, foil2] of mainRows) result.push(...makePair(bank, 'main_idea', 'mostly_about_info', id, 'What is this passage mostly about?', entry, harder, [entryKey, entryFoil1, entryFoil2], [key, foil1, foil2],
    { lower: 'Identify one clear informational topic against different topics.', higher: 'Integrate multiple functions or stages and reject two true but incomplete accounts.',
      entryFeatures: { competingTruePartialAccounts: 0 }, harderFeatures: { competingTruePartialAccounts: 2, requiredEvidenceParts: 2 } },
    { key: `“${key}” covers the connected parts of the account.`, foils: [`“${foil1}” is true but covers one part only.`, `“${foil2}” is true but covers a different part only.`] }));
  for (const [id, entry, harder, intervention, outcome, effects, causes] of causeRows) for (const claim of pairedClaims.cause_effect) {
    const prompt = claim === 'find_effect' ? `What happened because ${intervention}?`
      : claim === 'find_cause' ? causeQuestions[id] : `Which sentence explains why ${outcome}?`;
    const labels = claim === 'find_effect' ? effects.map(text => `${text[0].toUpperCase()}${text.slice(1)}.`)
      : claim === 'find_cause' ? causes.map(text => `${text[0].toUpperCase()}${text.slice(1)}.`)
        : causes.map(text => `${outcome[0].toUpperCase()}${outcome.slice(1)} because ${text}.`);
    result.push(...makePair(bank, 'cause_effect', claim, id, prompt, entry, harder, labels, labels,
      { lower: 'Retrieve an explicitly supplied cause-effect link.', higher: 'Compare trials to distinguish the changed cause from conditions that remained alike or changed after the outcome.',
        entryFeatures: { observationStates: 1, controlledAlternatives: 0 }, harderFeatures: { observationStates: 3, controlledAlternatives: 2 } },
      { key: `The account changes the relevant condition (${causes[0]}) while retaining or subsequently changing the competing conditions; the outcome is ${outcome}.`,
        foils: [`The second option names a real condition or later event, but the comparison does not connect it causally to ${outcome}.`, `The third option names a real condition or earlier event, but the comparison does not connect it causally to ${outcome}.`], cause: causes[0], effect: effects[0], controlledAlternatives: causes.slice(1) }));
  }
  for (const [id, entry, harder, key, foil1, foil2] of themeRows) result.push(...makePair(bank, 'theme', 'lesson_mistake_fixed', id, 'What lesson best fits the whole story?', entry, harder, [key, ...themeEntryFoils[id]], [key, foil1, foil2],
    { lower: 'Infer a lesson from one mistake and its successful correction.', higher: 'Infer the common transferable lesson across two different corrections, rejecting useful lessons that fit only one episode.',
      entryFeatures: { episodesToIntegrate: 1 }, harderFeatures: { episodesToIntegrate: 2, plausiblePartialLessons: 2 } },
    { key: `“${key}” applies to both characters’ different mistakes and repairs.`, foils: [`“${foil1}” fits only one episode.`, `“${foil2}” fits only the other episode.`] }));
  for (const [id, entryClaim, entry, entryKey, entryFoil1, entryFoil2, harderClaim, harder, key, foil1, foil2] of supportRows) result.push(...makePair(bank, 'informational_features', 'supporting_detail', id, `Which detail best supports this idea: ${harderClaim.slice(0, -1)}?`,
    // Preserve the single-property entry question as well as the extension
    // question; their response operation and access are identical.
    entry, harder, [entryKey, entryFoil1, entryFoil2], [key, foil1, foil2],
    { lower: `Select a detail supporting one stated property: ${entryClaim}`, higher: `Select a detail supporting both stated properties: ${harderClaim}`,
      entryFeatures: { requiredProperties: 1 }, harderFeatures: { requiredProperties: 2, onePropertyFoils: 2 } },
    { key: `“${key}” supports both properties of the stated idea.`, foils: [`“${foil1}” supports only one required property.`, `“${foil2}” supports only the other required property.`] }).map(item => item.level === 1 ? replacePrompt(item, `Which detail best supports this idea: ${entryClaim.slice(0, -1)}?`) : item));
  for (const [id, entry, harder, entryKey, entryFoil1, entryFoil2, key, foil1, foil2] of purposeRows) result.push(...makePair(bank, 'informational_features', 'purpose', id, 'What is the main purpose of this text?', entry, harder, [entryKey, entryFoil1, entryFoil2], [key, foil1, foil2],
    { lower: 'Recognize one clear purpose against unrelated purposes.', higher: 'Infer the whole text’s communicative purpose from its setup and intended reader response, rejecting purposes that cover background or one section only.',
      entryFeatures: { partialPurposeFoils: 0 }, harderFeatures: { partialPurposeFoils: 2 } },
    { key: `“${key}” explains why the whole text was written.`, foils: [`“${foil1}” addresses a supporting part, not the purpose of the whole text.`, `“${foil2}” addresses a different supporting part, not the purpose of the whole text.`] }));
  return result;
}

function replacePrompt(item, prompt) {
  const requiredAudioCues = [{ role: 'instruction', text: prompt, path: getLedaInstructionAudioPath(prompt) }];
  return { ...item, prompt, requiredAudioCues, requiredAudioPaths: requiredAudioCues.map(cue => cue.path).filter(Boolean),
    missingAudioCues: requiredAudioCues.filter(cue => !cue.path).map(({ role, text }) => ({ role, text })),
    mediaReady: requiredAudioCues.every(cue => Boolean(cue.path)) };
}
